-- Zero opening balances only. No grant, purchase, effect or scheduler activation.
CREATE TABLE crown_wallets(character_id uuid PRIMARY KEY REFERENCES characters(id),balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0));
CREATE TABLE crown_transactions(id uuid PRIMARY KEY,character_id uuid NOT NULL REFERENCES characters(id),kind text NOT NULL CHECK(kind IN('purchase','consume','refund','reversal')),amount bigint NOT NULL CHECK(amount<>0),balance_after bigint NOT NULL CHECK(balance_after>=0),provider text,provider_token_digest text,original_transaction_id uuid REFERENCES crown_transactions(id),idempotency_key uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(provider,provider_token_digest),CHECK(provider_token_digest IS NULL OR provider_token_digest ~ '^[a-f0-9]{64}$'),CHECK((kind='purchase' AND amount>0 AND provider IS NOT NULL AND provider_token_digest IS NOT NULL AND original_transaction_id IS NULL) OR (kind='consume' AND amount<0 AND original_transaction_id IS NULL) OR (kind IN('refund','reversal') AND amount<0 AND original_transaction_id IS NOT NULL)));
CREATE FUNCTION preserve_crown_transaction() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Crown ledger entries are immutable'; END $$;
CREATE TRIGGER crown_transaction_immutable BEFORE UPDATE OR DELETE ON crown_transactions FOR EACH ROW EXECUTE FUNCTION preserve_crown_transaction();
